const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action=(label,type,id='',attrs='')=>`<button class="council-button" data-action="council-${type}" data-id="${esc(id)}" ${attrs}>${esc(label)}</button>`;
export function councilEntry(topics){return `<section class="council-invitation" aria-labelledby="council-invite"><div><p class="eyebrow">NEW / TWO-ROUND COUNCILS</p><h2 id="council-invite">Win support.<br><em>Live with the promise.</em></h2><p>Three stakeholders. Private agendas. A shared work budget. Investigate and negotiate, then face what your commitments leave unfinished.</p></div><div class="council-entry-options">${topics.map(t=>`<article><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><button class="button" data-action="start-council" data-topic="${esc(t.id)}">Enter ${esc(t.title)} council <span aria-hidden="true">↗</span></button></article>`).join('')}</div></section>`;}
const capacity=(cost,total,label)=>`<div class="council-capacity"><span>${esc(label)}</span><strong>${cost}<small> / ${total}</small></strong><span>work units committed</span><meter min="0" max="${total}" value="${cost}" aria-label="${esc(label)}: ${cost} of ${total} work units"></meter><p>${total-cost} left for other work. Units are fictional effort estimates.</p></div>`;
function councilRound(v){return `<div class="council-guide"><b>Your move</b><span>1. Inspect up to two sources.</span><span>2. Choose a proposal and negotiate promises.</span><span>3. Chair the council. You can proceed without unanimity.</span></div><div class="council-layout"><div><section aria-labelledby="council-voices"><div class="section-line"><h2 id="council-voices">At the table</h2><span>PUBLIC VIEWS / PRIVATE AGENDAS</span></div><div class="council-people">${v.stakeholders.map(p=>`<article><div class="council-person-top"><span class="avatar" aria-hidden="true">${esc(p.name[0])}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.role)}</p></div></div><blockquote>${esc(p.claim)}</blockquote><div class="council-support" data-support="${esc(p.support)}"><strong>${esc(p.support==='supports'?'Will support':p.support==='opposes'?'Opposes':'Conditional')}</strong><p>${esc(p.condition)}</p></div></article>`).join('')}</div><p class="council-muted">Support reflects their interests. It is not an interview score or proof your decision is right.</p></section><section class="council-panel" aria-labelledby="council-evidence"><div class="section-line"><h2 id="council-evidence">Inspect the claims</h2><span>${v.investigationRemaining} OF 2 INSPECTIONS LEFT</span></div><p class="council-muted">Choose what to verify. Uninspected sources remain unknown during this council.</p><div class="council-records">${v.records.map(r=>`<article><h3>${esc(r.title)}</h3>${r.opened?`<p class="council-evidence-text" tabindex="-1" data-opened="${esc(r.id)}">${esc(r.text)}</p><span class="council-tag">Inspected</span>`:action('Inspect source','investigate',r.id,v.investigationRemaining?'':'disabled')}</article>`).join('')}</div></section><section class="council-panel" aria-labelledby="council-proposal"><p class="eyebrow">01 / YOUR PROPOSAL</p><h2 id="council-proposal">What will you commit to?</h2><div class="council-options" role="group" aria-labelledby="council-proposal">${v.proposals.map(p=>`<button class="council-option ${p.selected?'is-selected':''}" data-action="council-propose" data-id="${esc(p.id)}" aria-pressed="${!!p.selected}"><span class="council-option-top"><strong>${esc(p.title)}</strong><span aria-hidden="true">${p.selected?'●':'○'}</span></span><span>${esc(p.detail)}</span></button>`).join('')}</div></section><section class="council-panel" aria-labelledby="council-promises"><p class="eyebrow">02 / NEGOTIATE SUPPORT</p><h2 id="council-promises">Every promise takes capacity.</h2><p class="council-muted">Offer or withdraw a commitment before closing the council. Watch who changes their position. Accepted promises reserve next-round work; you cannot quietly take that capacity back.</p><div class="council-options">${v.commitments.map(p=>`<button class="council-option ${p.selected?'is-selected':''}" data-action="council-promise" data-id="${esc(p.id)}" aria-pressed="${!!p.selected}"><span class="council-option-top"><strong>${esc(p.title)}</strong><b>${p.cost} unit${p.cost===1?'':'s'}</b></span><span>${esc(p.detail)}</span><small>${p.selected?'Promised · click to withdraw':'Offer this commitment'}</small></button>`).join('')}</div></section></div><aside class="council-ledger">${capacity(v.cost,v.capacity,'Reserved for round 2')}<h3>Current positions</h3><ul class="council-position-list">${v.stakeholders.map(p=>`<li><b>${esc(p.name)}</b><span>${p.support==='supports'?'Supports':p.support==='opposes'?'Opposes':'Conditional'}</span></li>`).join('')}</ul><p>The proposal takes 2 units; promises come on top. Keep capacity for what emerges next.</p>${action('Close council & see consequences →','commit','',v.canCommit?'':'disabled')}<p class="council-muted">Your proposal and promises lock when the council closes. Unanimity is not required.</p></aside></div>`;}
function aftermath(v){const a=v.aftermath;return `<div class="council-update"><p class="eyebrow">THE NEXT ROUND / YOUR DECISION HAS ARRIVED</p><h2>${esc(a.summary)}</h2></div><div class="council-reactions">${a.reactions.map(r=>`<article><h3>${esc(r.name)}</h3><p>${esc(r.text)}</p></article>`).join('')}</div><div class="council-layout"><section class="council-panel"><p class="eyebrow">NOW / ALLOCATE THE REMAINING CAPACITY</p><h2>Promises first. What gets the rest?</h2><p class="council-muted">Locked work follows your first decision. Select additional work below; everything else carries forward unfinished. You may deliberately leave capacity unused.</p><div class="council-work">${a.work.map(w=>`<article class="${w.selected?'is-selected':''} ${w.locked?'is-locked':''}"><div class="council-option-top"><h3>${esc(w.title)}</h3><b>${w.cost} unit${w.cost===1?'':'s'}</b></div><p>${esc(w.detail)}</p>${w.locked?'<span class="council-tag">Reserved by your earlier decision · locked</span>':`${w.consequence?`<p class="council-deferral"><b>If left unfinished:</b> ${esc(w.consequence)}</p>`:''}${action(w.selected?'Remove from this round':'Fund this work','allocate',w.id,`aria-pressed="${!!w.selected}" ${!w.selected&&a.cost+w.cost>a.capacity?'disabled':''}`)}`}</article>`).join('')}</div></section><aside class="council-ledger">${capacity(a.cost,a.capacity,'Round 2 allocation')}<h3>Leaving work is a decision.</h3><p>Review the consequences beside each item. The debrief will show what was delivered and what remains open.</p>${action('Finish round & reveal agendas →','finish','',a.canFinish?'':'disabled')}<p class="council-muted">Unfunded work stays unfinished. This action does not complete it automatically.</p></aside></div>`;}
function debrief(v){const d=v.debrief;return `<div class="council-update"><p class="eyebrow">AFTER THE COUNCIL / THE FULL PICTURE</p><h2>${esc(d.summary)}</h2></div><section class="council-panel"><div class="section-line"><h2>The agendas behind the claims</h2><span>REVEALED AFTER YOUR DECISIONS</span></div><div class="council-reveals">${d.reveals.map(r=>`<article><h3>${esc(r.name)}</h3><p class="eyebrow">PRIVATE OBJECTIVE</p><p>${esc(r.objective)}</p><p class="council-muted">${esc(r.reflection)}</p></article>`).join('')}</div><p class="council-muted">You were not expected to know these motives in advance. Judge the claim against the evidence available at the time.</p></section><div class="council-results"><section><p class="eyebrow">DELIVERED THIS ROUND</p><h2>What moved forward</h2>${d.fulfilled.length?d.fulfilled.map(w=>`<article><h3>${esc(w.title)}</h3><p>${esc(w.result||w.detail)}</p></article>`).join(''):'<p>No work funded.</p>'}</section><section><p class="eyebrow">CARRIES FORWARD</p><h2>The unfinished work</h2>${d.deferred.length?d.deferred.map(w=>`<article><h3>${esc(w.title)}</h3><p>${esc(w.consequence||w.detail)}</p></article>`).join(''):'<p>No listed work remains unfinished.</p>'}</section></div><section class="council-panel"><p class="eyebrow">FOR YOUR INTERVIEW</p><h2>Explain the trade, not just the choice.</h2><ul class="council-feedback">${d.feedback.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></section><details class="council-trace"><summary>Your council record</summary><ol>${v.trace.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details><div class="council-replay">${action('Replay this council','replay')}<button class="text-button" data-action="back-practice">← Choose another practice</button><p>Replay uses the same agendas. It is a comparison, not a fresh hidden-role challenge.</p></div>`;}
export function councilMarkup(v,context,chat='',feedback=''){return `<div class="session-top"><button class="text-button" data-action="back-practice">← ${context==='interview'?'Preparation path':'Practice room'}</button><span class="eyebrow">COUNCIL / ${v.phase==='council'?'01 · NEGOTIATE':v.phase==='aftermath'?'02 · FOLLOW THROUGH':'DEBRIEF'}</span><span class="outline-badge">LOCAL PROTOTYPE</span></div><div class="council-heading"><p class="eyebrow">${context==='interview'?'FROM YOUR SELECTED JD RESPONSIBILITY':'GENERAL PRACTICE'} / TWO CONNECTED ROUNDS</p><h1 tabindex="-1">${esc(v.title)}</h1><p class="lede">${esc(v.intro)}</p></div>${feedback}${chat}<div id="council-status" role="status" aria-live="polite" tabindex="-1">${v.error?`<p class="notice">${esc(v.error)}</p>`:''}</div>${v.phase==='council'?councilRound(v):v.phase==='aftermath'?aftermath(v):debrief(v)}<p class="council-limits">Fictional scenario · prepared reactions and fixed agendas · no AI calls · progress clears on refresh. This prototype explores decisions, not employer grading.</p>`;}
